mapper.select:
/* BmsCargoMapper.selectPkgByPkgNo : 박스번호(+BL번호 조회옵션)로 박스 조회 */
SELECT TOP 1
	*
FROM TB_BMS_IN_PLAN_PKG WITH (NOLOCK)
WHERE PACKING_NO = #{packingNo}

	AND BL_NO = #{blNo}

	AND DELETE_YN = 'N'

/* BmsCargoMapper.selectPkg : 박스 조회 */
SELECT AA.* , COUNT(*) OVER() AS TOTAL_CNT FROM ( SELECT pkg.*,
outScan.PKG_OUT_SCAN_TIME, stockScan.STOCK_PKG_SCAN_TIME, '' AS STATUS FROM TB_BMS_IN_PLAN_PKG pkg WITH(NOLOCK)
OUTER APPLY ( SELECT TOP 1 REGISTER_DATE_TIME AS PKG_OUT_SCAN_TIME FROM TB_BMS_OUT_SCAN WITH (NOLOCK) WHERE SCAN_NO = pkg.PACKING_NO AND SCAN_RESULT = '완료' ) outScan OUTER APPLY ( SELECT TOP 1 REGISTER_DATE_TIME AS STOCK_PKG_SCAN_TIME FROM TB_BMS_STOCK_PKG_SCAN WITH (NOLOCK) WHERE SCAN_NO = pkg.PACKING_NO AND SCAN_RESULT = '완료' ) stockScan WHERE 1=1
AND IN_PLAN_NO = #{inPlanNo}
AND BL_NO = #{blNo}
AND DELETE_YN = 'N' ) AA

/* BmsCargoMapper.selectInList : 반입 조회 */
SELECT
	*
FROM TB_BMS_IN WITH (NOLOCK)
WHERE CARGO_REFERENCE_NO = #{cargoReferenceNo}

/* BmsCargoMapper.selectInspectResultNotCompleteByInNo : 반입번호로 검사 안된 검사결과리스트 조회 */
SELECT 
	* 
FROM TB_BMS_INSPECT_RESULT

WHERE IN_NO = #{inNo}
	AND INSPECTION_FINISH_YN = 'N'
